import{_ as e,o as a,c as r,a0 as o}from"./chunks/framework.BQGW-Zpy.js";const u=JSON.parse('{"title":"Partner Coverage by Corridor","description":"","frontmatter":{},"headers":[],"relativePath":"business/partner-coverage.md","filePath":"business/partner-coverage.md"}'),n={name:"business/partner-coverage.md"};function i(s,t,d,c,h,l){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="partner-coverage-by-corridor" tabindex="-1">Partner Coverage by Corridor <a class="header-anchor" href="#partner-coverage-by-corridor" aria-label="Permalink to &quot;Partner Coverage by Corridor&quot;">​</a></h1><p>Matched against the platform&#39;s actual supported currency list (<code>frontend/src/data/countries.js</code>) rather than generic examples.</p><h2 id="where-bvnk-is-strong" tabindex="-1">Where BVNK is strong <a class="header-anchor" href="#where-bvnk-is-strong" aria-label="Permalink to &quot;Where BVNK is strong&quot;">​</a></h2><p>BVNK holds 130+ countries on the payments side (150+ for virtual accounts), MiCA CASP authorisation (Malta FSA, Feb 2026, passported EEA-wide), UK EMI, and US MSB/MTL coverage. Strong fit for: <strong>USD, GBP, EUR, AED, SGD</strong>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Mastercard announced its acquisition of BVNK in March 2026 for up to $1.8B, larger than Stripe&#39;s 2024 Bridge acquisition, and further validation that card networks are moving to own stablecoin infrastructure rather than treat it as a threat.</p></div><h2 id="where-bvnk-s-own-material-shows-gaps-and-named-alternatives" tabindex="-1">Where BVNK&#39;s own material shows gaps, and named alternatives <a class="header-anchor" href="#where-bvnk-s-own-material-shows-gaps-and-named-alternatives" aria-label="Permalink to &quot;Where BVNK&#39;s own material shows gaps, and named alternatives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Region</th><th>Currencies on this platform</th><th>BVNK&#39;s own positioning</th><th>Alternative to name</th></tr></thead><tbody><tr><td>Latin America</td><td>MXN, BRL, COP, ARS</td><td>&quot;Weaker than AstroPay or PayRetailers&quot; for local methods (PIX, OXXO, Boleto); routes through <strong>Bitso</strong> for USDC liquidity</td><td><strong>Bitso</strong> (BVNK&#39;s own LatAm liquidity partner), or <strong>AstroPay</strong> / <strong>PayRetailers</strong> for deeper local-method coverage</td></tr><tr><td>South &amp; Southeast Asia</td><td>INR, PHP, PKR, BDT, IDR</td><td>&quot;Partner-driven&quot;, only Singapore has a native license; Thailand/Vietnam are case studies, not licensed coverage</td><td>Corridor-specific partner needed per market; not yet identified for INR/PHP specifically</td></tr></tbody></table><h2 id="africa-not-yet-confirmed-either-way" tabindex="-1">Africa, not yet confirmed either way <a class="header-anchor" href="#africa-not-yet-confirmed-either-way" aria-label="Permalink to &quot;Africa, not yet confirmed either way&quot;">​</a></h2><p>NGN, GHS, KES, UGX, TZS, ETB, EGP, MAD are all on this platform&#39;s currency list. No source reviewed here confirms or denies BVNK depth in these corridors specifically. <strong>Do not assume coverage</strong>, this needs its own targeted check before being stated as fact, consistent with this project&#39;s standard of not claiming a corridor is served without a named, checked partner.</p><h2 id="note" tabindex="-1">Note <a class="header-anchor" href="#note" aria-label="Permalink to &quot;Note&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Confidence</th><th>Corridors</th></tr></thead><tbody><tr><td>Named partner (BVNK), reasonably strong fit</td><td>USD, GBP, EUR, AED, SGD</td></tr><tr><td>Named alternative identified (Bitso / AstroPay / PayRetailers)</td><td>MXN, BRL, COP, ARS</td></tr><tr><td>Gap acknowledged, no alternative named yet</td><td>INR, PHP, PKR, BDT, IDR</td></tr><tr><td>Unconfirmed either way</td><td>NGN, GHS, KES, UGX, TZS, ETB, EGP, MAD</td></tr></tbody></table><p>This table should be updated as each remaining corridor is actually checked, not filled in with an assumed partner to make the list look complete.</p>',12)])])}const m=e(n,[["render",i]]);export{u as __pageData,m as default};
